import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"Installation — Apple","description":"Install the Apple admin theme on Pterodactyl Panel via Blueprint or the standalone variant — prerequisites, verification, troubleshooting and uninstall.","frontmatter":{"title":"Installation — Apple","description":"Install the Apple admin theme on Pterodactyl Panel via Blueprint or the standalone variant — prerequisites, verification, troubleshooting and uninstall."},"headers":[],"relativePath":"apple/getting-started/installation.md","filePath":"apple/getting-started/installation.md","lastUpdated":null}'),n={name:"apple/getting-started/installation.md"};function l(o,e,r,d,p,h){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Apple ships in two forms: a single <code>.blueprint</code> package (recommended, includes the settings hub) and a standalone variant for panels without Blueprint.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Requirement</th><th>Version</th></tr></thead><tbody><tr><td>Pterodactyl Panel</td><td><strong>1.12.x</strong></td></tr><tr><td>Blueprint framework</td><td><strong>beta-2026-05</strong> (Blueprint install only)</td></tr><tr><td>PHP</td><td><strong>8.2+</strong> (as required by the panel)</td></tr><tr><td>Python 3</td><td>any (standalone install only, for the layout patcher)</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Blueprint, not core edits</p><p>Apple is a Blueprint extension. It does not patch Pterodactyl core files to work, so panel updates keep working — but Blueprint itself must be installed and healthy first. Verify with <code>blueprint -v</code> on the panel server.</p></div><h2 id="install-blueprint" tabindex="-1">Install (Blueprint) <a class="header-anchor" href="#install-blueprint" aria-label="Permalink to &quot;Install (Blueprint)&quot;">​</a></h2><ol><li><p>Download <code>apple-v1.0.0.blueprint</code> and place it in the panel root (usually <code>/var/www/pterodactyl</code>).</p></li><li><p>From the panel root, run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apple-v1.0.0</span></span></code></pre></div></li><li><p>Open <strong>Admin → Apple Theme</strong>. Defaults apply on first load — the admin area is already themed before you touch a setting.</p></li></ol><div class="tip custom-block"><p class="custom-block-title">First-load behavior</p><p>On its very first page load Apple seeds every <code>apple::*</code> setting with the documented defaults. Nothing is written to your servers, nodes, or other extensions — only rows in the panel&#39;s own settings store.</p></div><h2 id="install-standalone" tabindex="-1">Install (standalone) <a class="header-anchor" href="#install-standalone" aria-label="Permalink to &quot;Install (standalone)&quot;">​</a></h2><p>Use this on panels <strong>without</strong> Blueprint:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PANEL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/var/www/pterodactyl</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> standalone/PanelFiles/.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PANEL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PTERODACTYL_DIRECTORY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PANEL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> standalone/data/install.sh</span></span></code></pre></div><p>The script copies the theme files, injects one marker-delimited <code>@include(&#39;apple.wrapper&#39;)</code> line into <code>resources/views/layouts/admin.blade.php</code> (the original is backed up first), installs the bento dashboard, and clears compiled views. It is idempotent — re-running it changes nothing.</p><div class="info custom-block"><p class="custom-block-title">Settings on standalone</p><p>The settings hub is a Blueprint-only feature. Standalone installs run with the documented defaults; each value can be adjusted directly in the panel <code>settings</code> table (keys <code>apple::*</code>) if you need to change one.</p></div><h2 id="post-install-verification" tabindex="-1">Post-install verification <a class="header-anchor" href="#post-install-verification" aria-label="Permalink to &quot;Post-install verification&quot;">​</a></h2><ol><li><strong>The sidebar and top bar</strong> appear on every admin page, and a branded loader flashes while they build.</li><li><strong>Admin → Apple Theme</strong> loads the settings hub (Blueprint installs).</li><li><strong>The admin dashboard</strong> renders the bento grid (greeting, stat tiles, sparkline, quick actions, system tile).</li><li><strong>Hard-refresh once</strong> (<code>Ctrl+Shift+R</code>) so your browser picks up the new assets.</li></ol><p>If the admin area ever looks unstyled after an update, clear the compiled views:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> view:clear</span></span></code></pre></div><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Likely cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>blueprint -i</code> says the package is invalid</td><td>Upload was corrupted or renamed</td><td>Re-download; keep the exact filename <code>apple-v1.0.0.blueprint</code></td></tr><tr><td><code>blueprint -i</code> / <code>-r</code> hangs with no output</td><td>A previous interrupted Blueprint run left a lock</td><td>Run <code>blueprint -unlock</code>, then retry</td></tr><tr><td>Blueprint asks for confirmation and aborts</td><td>Interactive prompt with no TTY</td><td>Answer the <code>y/N</code> prompt; avoid piping <code>yes</code> into Blueprint</td></tr><tr><td>Pages render but look stock</td><td>Browser or view cache</td><td><code>php artisan view:clear</code> + hard-refresh</td></tr><tr><td>Dashboard is stock after reinstall</td><td>Install hook raced the views copy</td><td>Already handled (the hook probes three locations); if you hit it, re-run <code>blueprint -i</code></td></tr><tr><td>Settings don&#39;t save (validation error)</td><td>A field outside its documented range</td><td>Check the red field hint against the <a href="./../../configuration/reference">Configuration Reference</a></td></tr><tr><td>Dashboard patch missing after uninstall</td><td>Backup was deleted manually</td><td>Restore <code>resources/views/admin/index.blade.php.apple-backup</code> by hand, or re-copy the stock view from the panel release</td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">Interrupted Blueprint runs and <code>.env</code></p><p>If a Blueprint install/remove is killed mid-flight it can leave <code>.env</code> re-quoted and a stale <code>.blueprint/lock</code>. If the panel starts 500-ing with database errors after an interrupted run, restore <code>.env</code> from your backup, then run <code>blueprint -unlock</code> and <code>php artisan config:clear</code>.</p></div><h2 id="uninstall-blueprint" tabindex="-1">Uninstall (Blueprint) <a class="header-anchor" href="#uninstall-blueprint" aria-label="Permalink to &quot;Uninstall (Blueprint)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">blueprint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apple</span></span></code></pre></div><p>The uninstaller restores the stock dashboard from its backup and makes a best-effort pass at removing Apple&#39;s settings (<code>apple::*</code> rows in the panel <code>settings</code> table). Your servers, users and other extensions are untouched, and the admin area returns to the stock layout immediately.</p><h2 id="uninstall-standalone" tabindex="-1">Uninstall (standalone) <a class="header-anchor" href="#uninstall-standalone" aria-label="Permalink to &quot;Uninstall (standalone)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PTERODACTYL_DIRECTORY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PANEL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> standalone/data/remove.sh</span></span></code></pre></div><p>This removes the wrapper include from the admin layout, restores the stock dashboard and deletes Apple&#39;s settings rows. Theme files under <code>public/apple</code> and <code>resources/views/apple</code> can then be removed manually.</p>`,26)])])}const k=t(n,[["render",l]]);export{u as __pageData,k as default};
